using System.IdentityModel.Tokens.Jwt;
using System.Net;
using System.Net.Http.Json;
using System.Text;
using Microsoft.IdentityModel.Tokens;
using WorkBoard.Api;
using Xunit;

namespace WorkBoard.Tests;

public sealed class HttpAcceptanceTests
{
    [Fact] public async Task Health_is_public() { using var api = new ApiFixture(); using var c = api.CreateClient(); var r = await c.GetAsync("/health"); Assert.Equal(HttpStatusCode.OK, r.StatusCode); Assert.Contains("ok", await r.Content.ReadAsStringAsync()); }
    [Fact] public async Task Unknown_route_is_404() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.NotFound, (await c.GetAsync("/unknown")).StatusCode); }
    [Fact] public async Task Login_issues_signed_identity_role_and_expiration()
    {
        using var api = new ApiFixture(); using var c = await api.Login(); var handler = new JwtSecurityTokenHandler { MapInboundClaims = false };
        var principal = handler.ValidateToken(c.DefaultRequestHeaders.Authorization!.Parameter!, new TokenValidationParameters { ValidateIssuerSigningKey = true, IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(ApiFixture.Key)), ValidateIssuer = true, ValidIssuer = ApiFixture.Issuer, ValidateAudience = true, ValidAudience = ApiFixture.Audience, ValidateLifetime = true, ClockSkew = TimeSpan.Zero }, out var validated);
        Assert.Equal("alice@example.test", principal.FindFirst("sub")?.Value); Assert.Equal("User", principal.FindFirst("role")?.Value);
        var jwt = Assert.IsType<JwtSecurityToken>(validated); Assert.Equal("HS256", jwt.Header.Alg); Assert.InRange(jwt.ValidTo - DateTime.UtcNow, TimeSpan.FromMinutes(14), TimeSpan.FromMinutes(16));
    }
    [Fact] public async Task Admin_has_signed_Admin_role() { using var api = new ApiFixture(); using var c = await api.Login("admin@example.test", "Admin!234"); var jwt = new JwtSecurityTokenHandler().ReadJwtToken(c.DefaultRequestHeaders.Authorization!.Parameter); Assert.Equal("Admin", jwt.Claims.Single(x => x.Type == "role").Value); }
    [Fact] public async Task Wrong_password_is_401() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.Unauthorized, (await c.PostAsJsonAsync("/api/auth/login", new LoginRequest("alice@example.test", "wrong"))).StatusCode); }
    [Fact] public async Task Unknown_account_is_401() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.Unauthorized, (await c.PostAsJsonAsync("/api/auth/login", new LoginRequest("nobody@example.test", "Alice!234"))).StatusCode); }
    [Fact] public async Task Blank_credentials_are_400() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/api/auth/login", new LoginRequest(" ", " "))).StatusCode); }
    [Fact] public async Task Anonymous_read_is_401() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.Unauthorized, (await c.GetAsync("/api/work-items")).StatusCode); }
    [Fact] public async Task Anonymous_mutations_are_rejected_before_execution() { using var api = new ApiFixture(); using var c = api.CreateClient(); Assert.Equal(HttpStatusCode.Unauthorized, (await c.PostAsJsonAsync("/api/work-items", new CreateWorkItemRequest("x"))).StatusCode); Assert.Equal(HttpStatusCode.Unauthorized, (await c.PutAsJsonAsync($"/api/work-items/{Guid.NewGuid()}", new UpdateWorkItemRequest("x", "Todo", 1))).StatusCode); Assert.Equal(HttpStatusCode.Unauthorized, (await c.DeleteAsync($"/api/work-items/{Guid.NewGuid()}?expectedVersion=1")).StatusCode); }
    [Fact] public async Task Malformed_token_is_401() { using var api = new ApiFixture(); using var c = api.CreateClient(); c.DefaultRequestHeaders.Authorization = new("Bearer", "malformed.jwt"); Assert.Equal(HttpStatusCode.Unauthorized, (await c.GetAsync("/api/work-items")).StatusCode); }
    [Fact] public async Task Expired_token_is_401() { using var api = new ApiFixture(); using var c = api.CreateClient(); c.DefaultRequestHeaders.Authorization = new("Bearer", ApiFixture.SignedToken(DateTime.UtcNow.AddMinutes(-10))); Assert.Equal(HttpStatusCode.Unauthorized, (await c.GetAsync("/api/work-items")).StatusCode); }
    [Fact] public async Task Wrong_signature_is_401() { using var api = new ApiFixture(); using var c = api.CreateClient(); c.DefaultRequestHeaders.Authorization = new("Bearer", ApiFixture.SignedToken(DateTime.UtcNow.AddMinutes(10), new string('x', 64))); Assert.Equal(HttpStatusCode.Unauthorized, (await c.GetAsync("/api/work-items")).StatusCode); }
    [Fact] public async Task Wrong_issuer_is_401() { using var api = new ApiFixture(); using var c = api.CreateClient(); c.DefaultRequestHeaders.Authorization = new("Bearer", ApiFixture.SignedToken(DateTime.UtcNow.AddMinutes(10), issuer: "wrong")); Assert.Equal(HttpStatusCode.Unauthorized, (await c.GetAsync("/api/work-items")).StatusCode); }
    [Fact] public async Task Wrong_audience_is_401() { using var api = new ApiFixture(); using var c = api.CreateClient(); c.DefaultRequestHeaders.Authorization = new("Bearer", ApiFixture.SignedToken(DateTime.UtcNow.AddMinutes(10), audience: "wrong")); Assert.Equal(HttpStatusCode.Unauthorized, (await c.GetAsync("/api/work-items")).StatusCode); }
    [Fact] public async Task Initial_collection_is_empty() { using var api = new ApiFixture(); using var c = await api.Login(); Assert.Empty((await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!); }
    [Fact] public async Task Create_trims_title_starts_version_one_and_returns_location() { using var api = new ApiFixture(); using var c = await api.Login(); var r = await c.PostAsJsonAsync("/api/work-items", new CreateWorkItemRequest("  Ship release  ", "InProgress")); Assert.Equal(HttpStatusCode.Created, r.StatusCode); var item = (await r.Content.ReadFromJsonAsync<WorkItemDto>())!; Assert.NotEqual(Guid.Empty, item.Id); Assert.Equal("Ship release", item.Title); Assert.Equal("InProgress", item.Status); Assert.Equal(1, item.Version); Assert.Equal($"/api/work-items/{item.Id}", r.Headers.Location?.OriginalString); Assert.Equal(item, (await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!.Single()); }
    [Fact] public async Task Create_blank_title_is_400_without_mutation() { using var api = new ApiFixture(); using var c = await api.Login(); Assert.Equal(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/api/work-items", new CreateWorkItemRequest(" "))).StatusCode); Assert.Empty((await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!); }
    [Fact] public async Task Create_title_over_120_is_400() { using var api = new ApiFixture(); using var c = await api.Login(); Assert.Equal(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/api/work-items", new CreateWorkItemRequest(new string('x', 121)))).StatusCode); }
    [Fact] public async Task Title_at_120_is_accepted() { using var api = new ApiFixture(); using var c = await api.Login(); Assert.Equal(120, (await ApiFixture.Create(c, new string('x', 120))).Title.Length); }
    [Fact] public async Task Invalid_status_is_400_without_mutation() { using var api = new ApiFixture(); using var c = await api.Login(); Assert.Equal(HttpStatusCode.BadRequest, (await c.PostAsJsonAsync("/api/work-items", new CreateWorkItemRequest("x", "Unknown"))).StatusCode); Assert.Empty((await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!); }
    [Fact] public async Task Update_increments_version_and_persists() { using var api = new ApiFixture(); using var c = await api.Login(); var item = await ApiFixture.Create(c); var r = await c.PutAsJsonAsync($"/api/work-items/{item.Id}", new UpdateWorkItemRequest("  Completed  ", "Done", 1)); Assert.Equal(HttpStatusCode.OK, r.StatusCode); var updated = (await r.Content.ReadFromJsonAsync<WorkItemDto>())!; Assert.Equal(item with { Title = "Completed", Status = "Done", Version = 2 }, updated); Assert.Equal(updated, (await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!.Single()); }
    [Fact] public async Task Stale_update_is_409_and_keeps_current_item() { using var api = new ApiFixture(); using var c = await api.Login(); var item = await ApiFixture.Create(c); await c.PutAsJsonAsync($"/api/work-items/{item.Id}", new UpdateWorkItemRequest("Current", "InProgress", 1)); Assert.Equal(HttpStatusCode.Conflict, (await c.PutAsJsonAsync($"/api/work-items/{item.Id}", new UpdateWorkItemRequest("Stale", "Done", 1))).StatusCode); Assert.Equal(item with { Title = "Current", Status = "InProgress", Version = 2 }, (await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!.Single()); }
    [Fact] public async Task Invalid_update_does_not_increment_or_mutate() { using var api = new ApiFixture(); using var c = await api.Login(); var item = await ApiFixture.Create(c); Assert.Equal(HttpStatusCode.BadRequest, (await c.PutAsJsonAsync($"/api/work-items/{item.Id}", new UpdateWorkItemRequest(" ", "Done", 1))).StatusCode); Assert.Equal(item, (await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!.Single()); }
    [Fact] public async Task Nonpositive_expected_version_is_400() { using var api = new ApiFixture(); using var c = await api.Login(); var item = await ApiFixture.Create(c); Assert.Equal(HttpStatusCode.BadRequest, (await c.PutAsJsonAsync($"/api/work-items/{item.Id}", new UpdateWorkItemRequest("New", "Done", 0))).StatusCode); Assert.Equal(HttpStatusCode.BadRequest, (await c.DeleteAsync($"/api/work-items/{item.Id}?expectedVersion=0")).StatusCode); Assert.Equal(item, (await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!.Single()); }
    [Fact] public async Task Unknown_item_is_404() { using var api = new ApiFixture(); using var c = await api.Login(); var id = Guid.NewGuid(); Assert.Equal(HttpStatusCode.NotFound, (await c.PutAsJsonAsync($"/api/work-items/{id}", new UpdateWorkItemRequest("x", "Todo", 1))).StatusCode); Assert.Equal(HttpStatusCode.NotFound, (await c.DeleteAsync($"/api/work-items/{id}?expectedVersion=1")).StatusCode); }
    [Fact] public async Task Delete_requires_current_version_then_removes_item() { using var api = new ApiFixture(); using var c = await api.Login(); var item = await ApiFixture.Create(c); Assert.Equal(HttpStatusCode.NoContent, (await c.DeleteAsync($"/api/work-items/{item.Id}?expectedVersion=1")).StatusCode); Assert.Empty((await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!); Assert.Equal(HttpStatusCode.NotFound, (await c.DeleteAsync($"/api/work-items/{item.Id}?expectedVersion=1")).StatusCode); }
    [Fact] public async Task Stale_delete_is_409_without_mutation() { using var api = new ApiFixture(); using var c = await api.Login(); var item = await ApiFixture.Create(c); await c.PutAsJsonAsync($"/api/work-items/{item.Id}", new UpdateWorkItemRequest("Current", "Done", 1)); Assert.Equal(HttpStatusCode.Conflict, (await c.DeleteAsync($"/api/work-items/{item.Id}?expectedVersion=1")).StatusCode); Assert.Equal(2, (await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!.Single().Version); }
    [Fact] public async Task Filter_selects_exact_status() { using var api = new ApiFixture(); using var c = await api.Login(); var todo = await ApiFixture.Create(c, "Todo item", "Todo"); var working = await ApiFixture.Create(c, "Working item", "InProgress"); var done = await ApiFixture.Create(c, "Done item", "Done"); Assert.Equal([todo.Id], (await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items?status=Todo"))!.Select(x => x.Id)); Assert.Equal([working.Id], (await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items?status=InProgress"))!.Select(x => x.Id)); Assert.Equal([done.Id], (await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items?status=Done"))!.Select(x => x.Id)); Assert.Equal(3, (await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!.Length); }
    [Fact] public async Task Invalid_filter_is_400() { using var api = new ApiFixture(); using var c = await api.Login(); Assert.Equal(HttpStatusCode.BadRequest, (await c.GetAsync("/api/work-items?status=unknown")).StatusCode); }
    [Fact] public async Task Other_owner_is_hidden_and_cannot_mutate() { using var api = new ApiFixture(); using var alice = await api.Login(); var item = await ApiFixture.Create(alice); using var bob = await api.Login("bob@example.test", "Bob!234"); Assert.Empty((await bob.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!); Assert.Equal(HttpStatusCode.NotFound, (await bob.PutAsJsonAsync($"/api/work-items/{item.Id}", new UpdateWorkItemRequest("Stolen", "Done", 1))).StatusCode); Assert.Equal(HttpStatusCode.NotFound, (await bob.DeleteAsync($"/api/work-items/{item.Id}?expectedVersion=1")).StatusCode); Assert.Equal(item, (await alice.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!.Single()); }
    [Fact] public async Task Owner_in_request_body_is_ignored() { using var api = new ApiFixture(); using var alice = await api.Login(); await alice.PostAsJsonAsync("/api/work-items", new { title = "Private", status = "Todo", owner = "bob@example.test" }); using var bob = await api.Login("bob@example.test", "Bob!234"); Assert.Empty((await bob.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!); Assert.Single((await alice.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!); }
    [Fact] public async Task Admin_does_not_bypass_private_ownership() { using var api = new ApiFixture(); using var alice = await api.Login(); var item = await ApiFixture.Create(alice); using var admin = await api.Login("admin@example.test", "Admin!234"); Assert.Empty((await admin.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!); Assert.Equal(HttpStatusCode.NotFound, (await admin.DeleteAsync($"/api/work-items/{item.Id}?expectedVersion=1")).StatusCode); }
    [Fact] public async Task Separate_server_instances_have_separate_storage() { using var first = new ApiFixture(); using var alice = await first.Login(); await ApiFixture.Create(alice); using var second = new ApiFixture(); using var other = await second.Login(); Assert.Empty((await other.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!); }
    [Fact] public async Task Concurrent_updates_admit_exactly_one_version() { using var api = new ApiFixture(); using var c = await api.Login(); var item = await ApiFixture.Create(c); var responses = await Task.WhenAll(Enumerable.Range(0, 8).Select(i => c.PutAsJsonAsync($"/api/work-items/{item.Id}", new UpdateWorkItemRequest($"Attempt {i}", "Done", 1)))); Assert.Single(responses.Where(x => x.StatusCode == HttpStatusCode.OK)); Assert.Equal(7, responses.Count(x => x.StatusCode == HttpStatusCode.Conflict)); Assert.Equal(2, (await c.GetFromJsonAsync<WorkItemDto[]>("/api/work-items"))!.Single().Version); }
}
